   "sql": "CREATE INDEX CONCURRENTLY IF NOT EXISTS orders_customer_id_idx ON orders (customer_id);"},
  {"note": "Check that the build finished and the index is valid and usable. If not, stop the plan here (a failed concurrent build leaves an INVALID index that has to be dropped with DROP INDEX CONCURRENTLY before trying again).",
   "sql": "DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_index i JOIN pg_class c ON c.oid = i.indexrelid WHERE c.relname = 'orders_customer_id_idx' AND i.indrelid = 'public.orders'::regclass AND i.indisvalid AND i.indisready) THEN RAISE EXCEPTION 'orders_customer_id_idx is missing or invalid'; END IF; END $$;"}
